  select id into sid from public.specialties where code=item->>'specialty';
  if sid is null then raise exception 'Missing canonical specialty'; end if;
  select id into aid from public.medical_areas where lower(name)=lower(item->>'area') limit 1;
  if aid is null then
   area_code:='V5_'||upper(substr(md5(item->>'area'),1,16));
   insert into public.medical_areas(code,name,description,is_active)
   values(area_code,item->>'area','Subárea da proposta curricular V5; revisão pendente.',false) returning id into aid;
  end if;
  insert into public.specialty_areas(specialty_id,area_id) values(sid,aid) on conflict do nothing;
  insert into public.themes(area_id,code,name,description,is_active)
  values(aid,'V5_'||upper(substr(md5((item->>'specialty')||':'||(item->>'area')),1,16)),(item->>'specialty')||': '||(item->>'area'),'Organização da proposta curricular V5.',false)
  on conflict(code) do nothing;
  select id into tid from public.themes where code='V5_'||upper(substr(md5((item->>'specialty')||':'||(item->>'area')),1,16));
  insert into public.subthemes(theme_id,code,name,description,is_active)
  values(tid,'V5_'||upper(substr(md5(tid::text),1,16)),'Competências propostas','Aguardando revisão médica.',false) on conflict(code) do nothing;
  select id into stid from public.subthemes where theme_id=tid and name='Competências propostas';
  insert into public.competencies(subtheme_id,code,name,description,is_active,curriculum_status,curriculum_source,search_terms)
  values(stid,item->>'code',item->>'name',item->>'description',false,'pending_review','owner-brief:2026-10-28:v5',array(select jsonb_array_elements_text(item->'terms')))
  on conflict(code) do nothing returning id into cid;
  if cid is not null then
   -- The legacy area trigger also attaches other specialties; restrict only this newly-created draft.
   delete from public.competency_specialties where competency_id=cid and specialty_id<>sid;
   insert into public.competency_specialties(competency_id,specialty_id,relationship) values(cid,sid,'primary') on conflict do nothing;
   insert into public.competency_objectives(competency_id,position,description)
   select cid,ordinality::smallint,value from jsonb_array_elements_text(item->'objectives') with ordinality;
  end if;
 end loop;
end $import$;
